{ <iptables> -C f2b-x -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-x || true; <iptables> -A f2b-x -j RETURN; }
for chain in $(echo 'FWD' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto --dport ssh -j f2b-x >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto --dport ssh -j f2b-x; }
done; done

{ <iptables> -C f2b-y -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-y || true; <iptables> -A f2b-y -j RETURN; }
for chain in $(echo 'INPUT' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto --dport http,https -j f2b-y >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto --dport http,https -j f2b-y; }
done; done

{ nft -a list chain inet mine f2b-chain | sed -nE 's/.*@<addr_set>\s+.*\s+\#\s*(handle\s+[0-9]+)$/\1/p'; } | while read -r hdl; do
nft delete rule inet mine f2b-chain $hdl; done
nft delete set inet mine <addr_set>
{ nft list table inet mine | grep -qE '^\s+set\s+'; } || {
nft delete table inet mine
}
